function submitGlobalSearch() {
  var e = jQuery("#subheader_search_box").val();
  var t = jQuery("input[name=selectName]").val();
  var r = jQuery("[name=subModSelText]").val();
  if (r == "") {
    if (sdp_app.IS_MSPOrSCP && !jQuery('[data-id="global_search"]').length) {
      if (
        jQuery("#globalSearchItems>li").eq(0).hasClass("selected") &&
        jQuery("#globalSearchItems>li").eq(0).find("ul").length
      ) {
        r = jQuery("#globalSearchItems > li")
          .eq(0)
          .find("ul")
          .find("li.selected")
          .attr("data-skey");
      }
    } else {
      if (
        jQuery("#globalSearchItems>li").eq(1).hasClass("selected") &&
        jQuery("#globalSearchItems>li").eq(1).find("ul").length
      ) {
        r = jQuery("#globalSearchItems > li")
          .eq(1)
          .find("ul")
          .find("li.selected")
          .attr("data-skey");
      }
    }
  }
  if (
    sdp_user.USERTYPE === "Requester" &&
    jQuery("#globalSearchItems > li.selected").attr("data-id") === "requests"
  ) {
    if (e.match(/^\d+$/)) {
      window.location.href =
        "/SearchN.do?searchText=" +
        encodeURIComponent(e) +
        "&subModSelText=" +
        encodeURIComponent(r) +
        "&selectName=" +
        encodeURIComponent(t);
    } else {
      if (e === "") {
        alert(translate("sdp.common.header.searchvaluemsg"));
      } else {
        alert(translate("sdp.mobileclient.search.nonnumeric.error"));
      }
      return false;
    }
  }
  if (e === "") {
    alert(translate("sdp.common.header.searchvaluemsg"));
    return false;
  } else if (t == "releases") {
    window.location.href =
      "/ui/releases?mode=get&gsearch=" + encodeURIComponent(e);
  } else if (t == "spaces") {
    $spa.navigate(
      "/ui/space?mode=list&module=space&gsearch=" + encodeURIComponent(e),
      "spaces",
      "spaces-list",
    );
    $header.searchBar("close");
  } else if (t == "problems") {
    $spa.navigate(
      "/ui/problems?mode=list&gsearch=" + encodeURIComponent(e),
      "problems",
    );
    $header.searchBar("close");
  } else if (t == "solutions") {
    window.location.href =
      "/ui/" + t + "?mode=list&gsearch=" + encodeURIComponent(e);
  } else if (t == "maintenances") {
    $spa.navigate(
      "/ui/maintenances?mode=list&gsearch=" + encodeURIComponent(e),
      "maintenances",
      "maintenances-list",
    );
    $header.searchBar("close");
  } else if (t == "assets") {
    window.location.href =
      "/ui/asset?module=asset_assets&gsearch=" + encodeURIComponent(e);
  } else if (t == "asset_computer") {
    window.location.href =
      "/ui/asset?module=asset_computers&gsearch=" + encodeURIComponent(e);
  } else if (t == "purchase") {
    window.location.href =
      "/PurchaseOrderList.do?gsearch=" + encodeURIComponent(e);
  } else if (t == "projects") {
    window.location.href =
      "/ui/projects?mode=list&gsearch=" + encodeURIComponent(e);
  } else if (t == "support") {
    window.location.href =
      "/app#/support/systemlogs?gsearch=" + encodeURIComponent(e);
  } else if (t == "software") {
    window.localStorage.search_text = e;
    window.location.href =
      "/SoftwareListView.do?searchText=" + encodeURIComponent(e);
  } else if (t == "assets" || t == "workstation") {
    const r = t == "assets" ? "assets" : "workstations";
    window.location.href =
      "/Assets.do?module=" +
      r +
      "&searchText=" +
      encodeURIComponent(e) +
      "&mode=get";
  } else if (t == "cis") {
    window.location.href =
      "/ui/cmdb_module?ci_type=cmdb&mode=list&gsearch=" + encodeURIComponent(e);
  } else {
    window.location.href =
      "/SearchN.do?searchText=" +
      encodeURIComponent(e) +
      "&subModSelText=" +
      encodeURIComponent(r) +
      "&selectName=" +
      encodeURIComponent(t);
  }
  return false;
}
var $extFrame = {
  setOptions: function (e) {
    if (window.externalframe) {
      let t = e
        ? jQuery(e).find("[data-externalframe]")
        : jQuery("[data-externalframe]");
      t.each(function (e) {
        let t = jQuery(this);
        const r = t.attr("rel");
        let i = "";
        if (t.data("externalframe") && t.attr("href")) {
          let e = new URL(this.href);
          if (e.search && e.search != "") {
            if (e.search.indexOf("externalframe") == -1) {
              e.search += "&externalframe=true";
            }
          } else {
            e.search += "?externalframe=true";
          }
          this.href = e;
          i = "noopener";
        } else {
          t.attr("target", "_blank");
          i = "noopener noreferrer";
        }
        if ((typeof r == "undefined" || r === false) && i != "") {
          t.attr("rel", i);
        }
      });
    }
  },
  getActiveWindow: function (e, t) {
    e = e ? e : parent.location.href;
    if (e) {
      if (!e.includes("externalframe=true")) return window.top;
    }
    let r = window.frameElement;
    let i = r ? r.ownerDocument : document;
    let n = i.defaultView || i.parentWindow;
    if (t) {
      let e = n.frameElement;
      if (t.getParentFrame) {
        return e;
      }
      if (t.getParentWindow) {
        let t = e.ownerDocument;
        return t.defaultView || t.parentWindow;
      }
    }
    return n;
  },
};
