function saveProfilePic() {
  setTimeout(function () {
    jQuery(".uitooltip-track").remove();
  }, 1);
  var e = jQuery("#profilepic").val();
  if (!e) {
    return false;
  }
  if (e.indexOf('"') > 0) {
    showalert(
      "failure",
      translate("profilepic.invalid.filename"),
      "isAutoHide=true",
    );
    jQuery("#profilepic").val("");
    return false;
  }
  var t = document.getElementById("profilepic").files[0];
  var r = new Array("jpg", "jpeg", "png", "bmp");
  var i = e.substring(e.lastIndexOf(".") + 1).toLowerCase();
  var n = false;
  for (var a = 0; a < r.length; a++) {
    if (r[a] == i) {
      n = true;
      break;
    }
  }
  if (!n) {
    showalert(
      "failure",
      translate("profilepic.invalidImageFileType"),
      "isAutoHide=true",
    );
    jQuery("#profilepic").val("");
    return false;
  }
  if (t.size > 5242880) {
    showalert(
      "failure",
      translate("profilepic.imageSizeExceed"),
      "isAutoHide=true",
    );
    jQuery("#profilepic").val("");
    return false;
  }
  var s = sdp_user.LOGGEDIN_USERID;
  var o = new FormData();
  o.append("input_image", t);
  var l = forwardfrom == "ESM" ? "orgusers" : "users";
  sdpAjax({
    processData: false,
    contentType: false,
    type: "put",
    url: "/api/v3/" + l + "/" + s + "/images",
    data: o,
    beforeSend: function () {
      jQuery("#alertbox").remove();
      showalert("info", translate("profilepic.uploading"), "isAutoHide=false");
    },
    success: function (e) {
      jQuery("#alertbox").remove();
      if (e.response_status.status === "success") {
        showalert(
          "success",
          translate("profilepic.uploadedMessage"),
          "isAutoHide=true",
        );
        jQuery("#prIconUpdated, .prp-circle-lx").removeClass("hide");
        jQuery("#prIcon, #uploadUserPrImg").addClass("hide");
        var t = new Date();
        var r = e.media["content-url"];
        jQuery("#prIconUpdated > img").removeAttr("src").attr("src", r);
        jQuery("#userPrImg").removeAttr("src").attr("src", r);
        if (jQuery(".user-button").val() != undefined) {
          jQuery("#prOnlineStatus").addClass("btn-success");
        } else {
          jQuery("#prOnlineStatus").removeClass("btn-success");
        }
      } else {
        showalert(
          "failure",
          translate("profilepic.errorOccurred"),
          "isAutoHide=true",
        );
      }
      jQuery("#profilepic").val("");
    },
    error: function (e) {
      jQuery("#alertbox").remove();
      var t = JSON.parse(e.responseText).response_status.messages[0].message;
      if (t === "INVALID_FILE_EXTENSION") {
        showalert(
          "failure",
          translate("sdp.security.invalid.extension"),
          "isAutoHide=true",
        );
      } else if (t === "UNMATCHED_FILE_CONTENT_TYPE") {
        showalert(
          "failure",
          translate("sdp.security.invalid.contenttype"),
          "isAutoHide=true",
        );
      } else if (t === "FILE_SIZE_MORE_THAN_ALLOWED_SIZE") {
        showalert(
          "failure",
          translate("sdp.common.maxattach.message", "5"),
          "isAutoHide=true",
        );
      } else if (t === "EMPTY_FILE_NOT_ALLOWED") {
        showalert(
          "failure",
          translate("sdp.common.minattach.message"),
          "isAutoHide=true",
        );
      } else {
        showalert("failure", t, "isAutoHide=true");
      }
    },
  });
  return true;
}
