function collapseSubHeader() {
  if (!subh_icon_collapsed) {
    var e = jD.find("#subheader-recent-items");
    if (e.length > 0) {
      e.detach().appendTo(".group-menu");
      e.find("> button").find("[data-name=recentItemclear]").hide();
      e.find("> button").attr("title", translate("common.recentitems"));
    }
    var t = jD.find("#sticky-notes");
    if (t.length > 0) {
      t.detach().appendTo(".group-menu");
      t.find("> button")
        .removeAttr("class")
        .addClass("btn btn-sm btn-default pb1");
      t.find("> button > span:first")
        .removeAttr("class")
        .addClass("cspr scriblepad");
    }
    subh_icon_collapsed = true;
    jD.find("#subheader-group-menu").removeClass("headerbtn-hide");
  }
  var r = jD.find("#subheader-show-menu");
  var i = jD.find("#subheader-more-tabs");
  var n = jD.find("#subheader-holder");
  var a = jQuery(window).width();
  var s = 0;
  while (a - n.width() < 1) {
    if (r.find("> div.toggle-tab:visible:first").length > 0) {
      i.prepend(
        "<li>" +
          r.find("> div.toggle-tab:visible:last").find("div").html() +
          "</li>",
      )
        .find("li:first > a")
        .removeAttr("class");
      i.parent().removeClass("headerbtn-hide");
      r.find("> div.toggle-tab:visible:last").addClass("headerbtn-hide");
    } else {
      break;
    }
    if (s > 5) {
      break;
    }
    s++;
  }
  if (r.find("> div.toggle-tab:visible").length == 0) {
    r.addClass("headerbtn-hide");
  }
}
function expandSubHeader(e) {
  var t = jD.find("#subheader-holder");
  var r = jQuery(window).width();
  if (t.length === 0) {
    return;
  }
  var i = jD.find("#subheader-more-tabs");
  var n = 0;
  while (e || r - t.width() > 150) {
    if (i.find("> li:first").length > 0) {
      i.find("> li:first").remove();
      t.find("#subheader-show-menu div:not(:visible):first").removeClass(
        "headerbtn-hide",
      );
      t.find("#subheader-show-menu").removeClass("headerbtn-hide");
    } else {
      break;
    }
    if (n > 5) {
      break;
    }
    n++;
  }
  if (e || i.find("> li:first").length == 0) {
    i.parent().addClass("headerbtn-hide");
  }
  if ((r - t.width() > 150 && subh_icon_collapsed) || e) {
    var a = jD.find("#subheader-recent-items");
    if (a.length > 0) {
      a.detach().appendTo(".show-menu");
      a.find("> button").find("[data-name=recentItemclear]").show();
      a.find("> button").attr("title", "");
    }
    var s = jD.find("#sticky-notes");
    if (s.length > 0) {
      s.detach().appendTo(".show-menu");
      s.find("> button").removeAttr("class").addClass("btn btn-link");
      s.find("> button > span:first")
        .removeAttr("class")
        .addClass("cspr scriblepad icon-lg");
    }
    subh_icon_collapsed = false;
    jD.find("#subheader-group-menu").addClass("headerbtn-hide");
  }
}
