function getTimeDiff(e, t) {
  var r;
  if (!t) {
    t = new Date().getTime();
  }
  e = parseInt(e);
  t = parseInt(t);
  var i = e >= t ? e - t : t - e;
  i = i / 1e3;
  if (i < 60) {
    r = translate("common.fewseconds");
  } else if (i >= 60 && i < 3600) {
    i = Math.floor(i / 60);
    r =
      i == 1
        ? i + " " + translate("sdp.requests.view.minute")
        : i + " " + translate("sdp.requests.view.minutes");
  } else if (i >= 3600 && i < 86400) {
    i = Math.floor(i / 3600);
    r =
      i == 1
        ? i + " " + translate("sdp.requests.view.hour")
        : i + " " + translate("sdp.requests.view.hours");
  } else {
    i = Math.floor(i / 86400);
    r =
      i == 1
        ? i + " " + translate("sdp.requests.view.day")
        : i + " " + translate("sdp.requests.view.days");
  }
  return r;
}
function isTemplateAvailable(e) {
  var t = template_obj.cloneCategories();
  if (t === undefined) {
    return false;
  }
  var r = t;
  for (var i = 0, n = r.length; i < n; i++) {
    for (var a = 0, s = r[i].templates.length; a < s; a++) {
      if (e == r[i].templates[a].id) {
        return true;
      }
    }
  }
  return false;
}
