  searchCategories: function (e) {
    e.off("keyup").on("keyup", function () {
      var e = jQuery(this).val();
      e = e ? e.toLowerCase() : "";
      var t = jQuery(this).closest(".sdtab-pane");
      t.find(".noitem").addClass("hide");
      t.find("li").each(function (t, r) {
        var i = jQuery(r);
        var n = i.text();
        n = n ? n.toLowerCase() : "";
        if (n.indexOf(e) !== -1) {
          i.removeClass("hide").addClass("show");
        } else {
          i.addClass("hide").removeClass("show");
        }
      });
      t.find(".panel").each(function () {
        var e = jQuery(this);
        if (e.find("li.show").length) {
          e.show();
        } else {
          e.hide();
        }
      });
      if (e) {
        t.find(".panel").each(function () {
          var t = jQuery(this);
          var r = t.find(".panel-heading").text();
          r = r ? r.toLowerCase() : "";
          if (r.indexOf(e) !== -1) {
            t.show();
            if (!t.find("li.show").length) {
              t.find("li").removeClass("hide").addClass("show");
            }
          } else {
            if (!t.find("li.show").length) {
              t.hide();
            }
          }
        });
      }
      if (t.find(".panel:visible").length) {
        t.find(".noitem").addClass("hide");
      } else {
        t.find(".noitem").removeClass("hide");
      }
    });
  },
