  initResizeHeader: function () {
    var e = jQuery("body").attr("data-header-tabs");
    jQuery("#sdp-tabs li[data-index]").each(function () {
      if (e === "topbar") {
        if (!jQuery(this).parent().hasClass("overflow-menu-ul")) {
          jQuery(this).attr("data-width", jQuery(this).outerWidth());
        }
      } else {
        if (!jQuery(this).parent().hasClass("overflow-menu-ul")) {
          jQuery(this).attr("data-height", jQuery(this).outerHeight());
        }
      }
    });
  },
  loadHeaderTabsManager: function (e, t) {
    e.stopImmediatePropagation();
    if (typeof headerTabManager == "undefined") {
      let r = ["/scripts/manage_tabs_min.js", "/scripts/hbs-template-tabs.js"];
      let i = ["/scripts/home_scripts.js", "/scripts/hbs-template-home.js"];
      let n;
      let a = i.concat("/scripts/hbs-template-tabs.js");
      if (
        typeof headerTabManager !== "undefined" &&
        headerTabManager.isHomeFiles
      ) {
        headerTabManager.isHomeFiles = false;
        n = i;
      } else {
        n = r.concat(i);
      }
      if (window.location.hash.includes("/manage-tabs")) {
        n = n.filter((e) => !r.includes(e));
      }
      if (sdp_app.IS_DEVELOPMENT_MODE) {
        a = [
          "/scripts/home.js",
          "/scripts/dashboard_common.js",
          "/scripts/SelfServiceCustomization_TechnicianScript.js",
        ];
        n = ["/scripts/headerTabsManager.js", ...a];
        if (window.location.hash.includes("/manage-tabs")) {
          n = n.filter((e) => e !== "/scripts/headerTabsManager.js");
        }
      }
      if (window.location.pathname == "/ui/home") {
        n = n.filter((e) => !a.includes(e));
      }
      ResourceLoader({
        js: n,
        success: function () {
          headerTabManager.getGlobalPersonalizationId("organize_tab");
          headerTabManager.isHomeFiles = false;
          headerTabManager.isFilesLoaded = true;
          headerTabManager.openPanel(e, t, undefined);
        },
      });
    } else {
      headerTabManager.openPanel(e, t, undefined);
    }
  },
