function onChangeTemplate(e, t, r) {
  var i;
  var n;
  var a;
  if (r == "telephony") {
    a = jQuery(e).parents("#create_req").find("#temp_selection");
    i = template_obj.cloneCategories();
    n = "templates";
    var s = a;
  } else if (r == "chat") {
    var o = jQuery(e).parents("#close_create_req");
    a = o.find("#temp_selection");
    var l = o.find("#close_create_request");
    var c = o.find("#close_chat");
    if (!l.hasClass("hide")) {
      l.removeClass().addClass("btn btn-default mr10");
      c.removeClass().addClass("btn btn-primary mr10");
    }
    var u = o.find("#close_chat").attr("data-chatid");
    var d = jQuery("#sdp-chat-bar #" + u).attr("data-portalid");
    if (d != PORTALID) {
      i = portal_template_obj.service_categories;
      n = "request_templates";
    } else {
      i = template_obj.cloneCategories();
      n = "templates";
    }
    var s = a;
  }
  a.find("option,optgroup").remove().end();
  a.select2("data", null);
  jQuery("<option>")
    .val("0")
    .text(translate("common.select.templates"))
    .appendTo(a);
  if (t === "incident") {
    jQuery.each(i, function (e, t) {
      jQuery.each(t[n], function (e, t) {
        if (!t.is_service_template) {
          jQuery("<option>").val(t.id).text(t.name).appendTo(a);
        }
      });
    });
  } else if (t === "service") {
    jQuery.each(i, function (e, t) {
      s.append(
        '<optgroup label="' +
          e_attr(t.name) +
          '" id="' +
          t.id +
          '"></optgroup>',
      );
      htmlOpts = [];
      jQuery.each(t[n], function (e, t) {
        if (t.is_service_template) {
          htmlOpts.push(jQuery(new Option(t.name, t.id)));
        }
      });
      s.find("optgroup:last").append(htmlOpts);
    });
  }
  a.select2("val", "0");
}
