function getCustomizedTime(e) {
  var t = new Date();
  var r = t.getTime();
  var i = r + 330 * 60 * 1e3;
  var n = i - e;
  var a = getTimeString(n);
  return a;
}
function getTimeString(e) {
  var t = 24 * 60 * 60 * 1e3,
    r = 60 * 60 * 1e3,
    i = 60 * 1e3,
    n = Math.floor(e / t),
    a = Math.floor((e - n * t) / r),
    s = Math.floor((e - n * t - a * r) / i),
    o = Math.round((e - n * t - a * r - s * i) / 1e3),
    l = 0,
    c = 0,
    u = 0,
    d = "";
  if (o === 60) {
    s++;
    o = 0;
  }
  if (s === 60) {
    a++;
    s = 0;
  }
  if (a == 24) {
    n++;
    a = 0;
  }
  if (n >= 7) {
    l = Math.floor(n / 7);
  }
  if (l >= 4) {
    c = Math.floor(l / 4);
  }
  if (c >= 12) {
    u = Math.floor(c / 12);
  }
  if (u === 1) {
    d = "1 year ago";
  } else if (u > 1) {
    d = u + " years ago";
  } else if (c === 1) {
    d = "1 month ago";
  } else if (c > 1) {
    d = c + " months ago";
  } else if (l === 1) {
    d = "1 week ago";
  } else if (l > 1) {
    d = l + " weeks ago";
  } else if (n === 1) {
    d = "1 day ago";
  } else if (n > 1) {
    d = n + " days ago";
  } else if (a === 1) {
    d = "1 hour ago";
  } else if (a > 1) {
    d = a + " hours ago";
  } else if (s === 1) {
    d = "1 minute ago";
  } else if (s > 1) {
    d = s + " minutes ago";
  } else if (o === 1) {
    d = "1 second ago";
  } else if (o > 1) {
    d = o + " seconds ago";
  }
  return d;
}
